package edu.portal.web;
import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcPortalRepository { private final JdbcTemplate db; public JdbcPortalRepository(JdbcTemplate db){this.db=db;}
 public int count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 public List<Map<String,Object>> students(String q){return db.queryForList("SELECT s.*,d.name department FROM student s JOIN department d USING(department_id) WHERE s.name LIKE ? OR s.email LIKE ? ORDER BY s.student_id",'%'+q+'%','%'+q+'%');}
 public List<Map<String,Object>> departments(){return db.queryForList("SELECT * FROM department ORDER BY name");}
 public void saveStudent(StudentForm f){if(f.studentId==null)db.update("INSERT INTO student(name,department_id,qualification,skills,cgpa,email,phone) VALUES(?,?,?,?,?,?,?)",f.name,f.departmentId,f.qualification,f.skills,f.cgpa,f.email,f.phone);else db.update("UPDATE student SET name=?,department_id=?,qualification=?,skills=?,cgpa=?,email=?,phone=? WHERE student_id=?",f.name,f.departmentId,f.qualification,f.skills,f.cgpa,f.email,f.phone,f.studentId);}
 public Map<String,Object> student(int id){return db.queryForMap("SELECT * FROM student WHERE student_id=?",id);} public void deleteStudent(int id){db.update("DELETE FROM student WHERE student_id=?",id);}
 public List<Map<String,Object>> companies(){return db.queryForList("SELECT * FROM company ORDER BY name");} public Map<String,Object> company(int id){return db.queryForMap("SELECT * FROM company WHERE company_id=?",id);} public void saveCompany(CompanyForm f){if(f.companyId==null)db.update("INSERT INTO company(name,industry,location,contact) VALUES(?,?,?,?)",f.name,f.industry,f.location,f.contact);else db.update("UPDATE company SET name=?,industry=?,location=?,contact=? WHERE company_id=?",f.name,f.industry,f.location,f.contact,f.companyId);} public void deleteCompany(int id){db.update("DELETE FROM company WHERE company_id=?",id);}
 public List<Map<String,Object>> vacancies(){return db.queryForList("SELECT v.*,c.name company FROM vacancy v JOIN company c USING(company_id) ORDER BY v.vacancy_id DESC");}
 public List<Map<String,Object>> applications(String status){return db.queryForList("SELECT a.*,s.name student,c.name company,v.job_title FROM application a JOIN student s USING(student_id) JOIN vacancy v USING(vacancy_id) JOIN company c USING(company_id) WHERE (?='' OR a.status=?) ORDER BY a.application_date DESC",status,status);}
 public void apply(int student,int vacancy){db.update("CALL apply_for_vacancy(?,?)",student,vacancy);} public void status(int id,String target){db.update("UPDATE application SET status=? WHERE application_id=?",target,id);}
 public List<Map<String,Object>> report(String view){return db.queryForList("SELECT * FROM "+view);} }
